/* SD Akademie P5: Fortgeschritten – saubere Web-Apps. */
(function(root){"use strict";root.SDAkademieKurse=root.SDAkademieKurse||Object.create(null);root.SDAkademieKurse["saubere-webapps"]=[{"id":"p5-1","title":"Code in Funktionen und Dateien aufteilen","minutes":35,"ziel":"Eine wartbare Aufgabenliste organisieren","schritte":[{"titel":"Verantwortung erkennen","text":"Bei einer Aufgabenliste gibt es drei verschiedene Tätigkeiten: eine Aufgabe anlegen, sie speichern und sie anzeigen. Wenn du alle Schritte in einen einzigen Klick-Handler schreibst, musst du später an vielen Stellen gleichzeitig Änderungen vornehmen. Notiere zuerst, welche Aufgabe jede Funktion übernehmen soll. `aufgabeErstellen` erzeugt nur Daten und berührt die Webseite nicht. Diese Trennung macht die Funktion leicht zu verstehen und unabhängig testbar.","code":"function aufgabeErstellen(text) { return { text, erledigt: false }; }\nconst aufgabe = aufgabeErstellen('Brief schreiben');\ndocument.querySelector('#ausgabe').textContent = aufgabe.text;","erklaerung":"Bei einer Aufgabenliste gibt es drei verschiedene Tätigkeiten: eine Aufgabe anlegen, sie speichern und sie anzeigen."},{"titel":"Datenfunktion schreiben","text":"Eine Werkstatt bewahrt Werkzeuge nach ihrem Zweck auf. `function aufgabeErstellen(text) { return { text, erledigt: false }; }` erhält einen Text und gibt ein neues Objekt zurück. Das Objekt enthält den Aufgabentext und den Status. Ein Funktionsname soll eine Handlung beschreiben. Übergib den Text als Parameter statt heimlich auf ein Eingabefeld zuzugreifen; so kann die Funktion auch in einem Test benutzt werden.","code":"function aufgabeErstellen(text) { return { text, erledigt: false }; }\nconst aufgabe = aufgabeErstellen('Brief schreiben');\ndocument.querySelector('#ausgabe').textContent = aufgabe.text;","erklaerung":"Eine Werkstatt bewahrt Werkzeuge nach ihrem Zweck auf."},{"titel":"Darstellung getrennt halten","text":"Die Anzeige ist wie ein Schaufenster: Sie zeigt Daten, erzeugt sie aber nicht selbst. `const aufgabe = aufgabeErstellen('Brief schreiben');` erzeugt das Objekt. `document.querySelector('#ausgabe').textContent = aufgabe.text;` schreibt den Text in ein Element. Wenn du später ein anderes Layout möchtest, bleibt die Datenfunktion unverändert. Prüfe mit einer zweiten Aufgabe, ob der gleiche Ablauf funktioniert.","code":"function aufgabeErstellen(text) { return { text, erledigt: false }; }\nconst aufgabe = aufgabeErstellen('Brief schreiben');\ndocument.querySelector('#ausgabe').textContent = aufgabe.text;","erklaerung":"Die Anzeige ist wie ein Schaufenster: Sie zeigt Daten, erzeugt sie aber nicht selbst."},{"titel":"Dateien sinnvoll benennen","text":"Ein größeres Projekt kann `daten.js`, `ansicht.js` und `app.js` verwenden. `daten.js` enthält reine Datenfunktionen, `ansicht.js` kümmert sich um DOM-Elemente, `app.js` verbindet beide. Ein Modul importiert nur das, was es benötigt. Vermeide kreisförmige Abhängigkeiten, bei denen Dateien sich gegenseitig laden. Beginne bei einem kleinen Projekt mit wenigen klaren Dateien und teile erst auf, wenn eine Verantwortung deutlich erkennbar ist.","code":"function aufgabeErstellen(text) { return { text, erledigt: false }; }\nconst aufgabe = aufgabeErstellen('Brief schreiben');\ndocument.querySelector('#ausgabe').textContent = aufgabe.text;","erklaerung":"Ein größeres Projekt kann `daten.js`, `ansicht.js` und `app.js` verwenden."}],"beispiel":{"html":"<h1>Code in Funktionen und Dateien aufteilen</h1><p id='ausgabe'></p>","css":"","js":"function aufgabeErstellen(text) { return { text, erledigt: false }; }\nconst aufgabe = aufgabeErstellen('Brief schreiben');\ndocument.querySelector('#ausgabe').textContent = aufgabe.text;"},"aufgabe":{"text":"Setze „Code in Funktionen und Dateien aufteilen“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.","tipp":"Lies den zugehörigen Schritt und vergleiche den Code mit dem erklärten Verhalten.","pruefungen":[{"beschreibung":"Die Oberfläche enthält die benötigten Elemente.","test":"p5-1-html"},{"beschreibung":"Die Technik wurde in JavaScript verwendet.","test":"p5-1-js"}],"loesung":{"html":"<h1>Code in Funktionen und Dateien aufteilen</h1><p id='ausgabe'></p>","css":"","js":"function aufgabeErstellen(text) { return { text, erledigt: false }; }\nconst aufgabe = aufgabeErstellen('Brief schreiben');\ndocument.querySelector('#ausgabe').textContent = aufgabe.text;"}},"fehler":[{"titel":"Versteckte DOM-Abhängigkeit","text":"Falsch: `function aufgabeErstellen(){ return document.querySelector('#eingabe').value; }` ist ohne Webseite schwer testbar. Richtig: `function aufgabeErstellen(text){ return {text}; }` erhält seine Eingabe ausdrücklich als Parameter."},{"titel":"Rückgabe vergessen","text":"Falsch: `function aufgabeErstellen(text){ const a={text}; }` liefert `undefined`, obwohl ein Objekt erzeugt wird. Richtig: `function aufgabeErstellen(text){ return {text}; }` gibt das Ergebnis an den Aufrufer zurück."}],"quiz":[{"frage":"Welche Funktion lässt sich leichter testen?","antworten":["Ein Klick-Handler mit vielen globalen Variablen","Ein unbenannter Seiteneffekt","Eine reine Datenfunktion"],"richtig":2,"erklaerung":"Eine Datenfunktion ist ohne Browser und versteckte Zustände leichter überprüfbar.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein."]},{"frage":"Wozu dient return?","antworten":["Zum Zurückgeben eines Wertes","Zum Ändern von CSS","Zum Öffnen einer Datei"],"richtig":0,"erklaerung":"return gibt das erstellte Aufgabenobjekt an die aufrufende Stelle zurück.","begruendungen":["Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Welche Datei sollte die DOM-Anzeige verwalten?","antworten":["daten.js","ansicht.js","package.json"],"richtig":1,"erklaerung":"Die Darstellung gehört in eine eigene Datei, weil DOM-Code nicht Teil der Datenlogik sein muss.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion."]}],"merke":["Eine Werkstatt bewahrt Werkzeuge nach ihrem Zweck auf.","Ein größeres Projekt kann `daten.js`, `ansicht.js` und `app.js` verwenden."]},{"id":"p5-2","title":"Eingaben prüfen und XSS vermeiden","minutes":35,"ziel":"Fremde Texte sicher anzeigen","schritte":[{"titel":"Unbekannte Eingaben erkennen","text":"Ein öffentliches Gästebuch nimmt Texte von Menschen entgegen, die du nicht kennst. Manche Eingaben enthalten Zeichen wie `<` oder `>`, die in HTML eine besondere Bedeutung haben. Ein fremder Text ist zunächst nur Dateninhalt und darf nicht als Anweisung behandelt werden. Lies einen Beispieltext ein und stelle dir vor, jemand fügt HTML-Tags statt eines Namens ein. Die sichere Anzeige muss auch dann verständlich bleiben.","code":"const eingabe = '<img src=x onerror=alert(1)>';\nconst ausgabe = document.querySelector('#ausgabe');\nausgabe.textContent = eingabe;","erklaerung":"Ein öffentliches Gästebuch nimmt Texte von Menschen entgegen, die du nicht kennst."},{"titel":"textContent verwenden","text":"Auf einer Anzeigetafel wird eine Nachricht als Text gedruckt, nicht als Bauanleitung interpretiert. `ausgabe.textContent = eingabe;` setzt genau den Textinhalt eines Elements. Selbst wenn die Eingabe wie ein HTML-Tag aussieht, erzeugt diese Zuweisung daraus kein neues Bild oder Skript. Das ist für nutzergenerierte Texte der richtige Standard. Probiere normale Namen und eine Zeichenfolge mit spitzen Klammern aus.","code":"const eingabe = '<img src=x onerror=alert(1)>';\nconst ausgabe = document.querySelector('#ausgabe');\nausgabe.textContent = eingabe;","erklaerung":"Auf einer Anzeigetafel wird eine Nachricht als Text gedruckt, nicht als Bauanleitung interpretiert."},{"titel":"Gefährliche Alternative verstehen","text":"`innerHTML` interpretiert den zugewiesenen String als HTML-Struktur. Wenn dieser String aus einer unkontrollierten Eingabe stammt, kann daraus Cross-Site-Scripting entstehen. Auch das Einfügen von HTML aus einer externen JSON-Datei ist nicht automatisch sicher. Verwende `createElement` und `textContent`, wenn du Elemente dynamisch bauen möchtest. Füge keine fremden Inhalte ungeprüft in HTML-Attribute oder URLs ein.","code":"const eingabe = '<img src=x onerror=alert(1)>';\nconst ausgabe = document.querySelector('#ausgabe');\nausgabe.textContent = eingabe;","erklaerung":"`innerHTML` interpretiert den zugewiesenen String als HTML-Struktur."},{"titel":"Weitere Schutzschichten","text":"Eine sichere App prüft zusätzlich, ob Eingaben plausibel sind. Für einen Anzeigenamen kannst du Länge und erlaubte Form prüfen; die genaue Regel hängt vom Zweck ab. Eine Content-Security-Policy kann zusätzliche Schäden begrenzen, ersetzt aber keine sichere Ausgabe. Berechtigungen gehören auf den Server, falls ein Server beteiligt ist. Eine rein lokale Vorschau bietet keine Zugriffskontrolle für fremde Benutzer.","code":"const eingabe = '<img src=x onerror=alert(1)>';\nconst ausgabe = document.querySelector('#ausgabe');\nausgabe.textContent = eingabe;","erklaerung":"Eine sichere App prüft zusätzlich, ob Eingaben plausibel sind."}],"beispiel":{"html":"<h1>Eingaben prüfen und XSS vermeiden</h1><p id='ausgabe'></p>","css":"","js":"const eingabe = '<img src=x onerror=alert(1)>';\nconst ausgabe = document.querySelector('#ausgabe');\nausgabe.textContent = eingabe;"},"aufgabe":{"text":"Setze „Eingaben prüfen und XSS vermeiden“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.","tipp":"Lies den zugehörigen Schritt und vergleiche den Code mit dem erklärten Verhalten.","pruefungen":[{"beschreibung":"Die Oberfläche enthält die benötigten Elemente.","test":"p5-2-html"},{"beschreibung":"Die Technik wurde in JavaScript verwendet.","test":"p5-2-js"}],"loesung":{"html":"<h1>Eingaben prüfen und XSS vermeiden</h1><p id='ausgabe'></p>","css":"","js":"const eingabe = '<img src=x onerror=alert(1)>';\nconst ausgabe = document.querySelector('#ausgabe');\nausgabe.textContent = eingabe;"}},"fehler":[{"titel":"Fremden Text als HTML einsetzen","text":"Falsch: `ausgabe.innerHTML = eingabe;` interpretiert HTML-Zeichen aus einer unbekannten Nachricht. Richtig: `ausgabe.textContent = eingabe;` zeigt die Nachricht als Text und verhindert diese Art von HTML-Ausführung."},{"titel":"Validierung als alleinigen Schutz betrachten","text":"Falsch: `if (eingabe.length < 100) ausgabe.innerHTML = eingabe;` kann trotz kurzer Eingabe gefährliche HTML-Inhalte ausführen. Richtig: `if (eingabe.length < 100) ausgabe.textContent = eingabe;` kombiniert Plausibilitätsprüfung und sichere Ausgabe."}],"quiz":[{"frage":"Welche Eigenschaft zeigt fremde Texte ohne HTML-Interpretation?","antworten":["textContent","innerHTML","outerHTML"],"richtig":0,"erklaerung":"textContent setzt einen Textknoten statt HTML-Markup aus der Eingabe zu erzeugen.","begruendungen":["Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Was bedeutet XSS?","antworten":["Eine Dateiendung","Ein CSS-Raster","Ausführung eingeschleuster Inhalte im Seitenkontext"],"richtig":2,"erklaerung":"XSS kann entstehen, wenn Angreifer Inhalte im Kontext einer fremden Webseite ausführen.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein."]},{"frage":"Was ist bei fremden Daten richtig?","antworten":["Alles als HTML einfügen","Nur die Länge prüfen","Daten und HTML-Struktur trennen"],"richtig":2,"erklaerung":"Unbekannte Eingaben bleiben Daten und werden nicht ungeprüft als HTML-Struktur interpretiert.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein."]}],"merke":["Auf einer Anzeigetafel wird eine Nachricht als Text gedruckt, nicht als Bauanleitung interpretiert.","Eine sichere App prüft zusätzlich, ob Eingaben plausibel sind."]},{"id":"p5-3","title":"Performance messen und DOM-Arbeit reduzieren","minutes":35,"ziel":"Eine Liste effizient und nachvollziehbar rendern","schritte":[{"titel":"Langsame Stellen finden","text":"Eine lange Teilnehmerliste kann beim Aufbau stocken. Bevor du etwas optimierst, miss die tatsächliche Dauer. `performance.now()` liefert eine hochauflösende Zeitangabe. Speichere die Zeit vor und nach dem Rendern und berechne die Differenz. Ein einzelner Messwert schwankt; wiederhole die Messung mit gleich großen Datenlisten. Ohne Messung ist eine vermeintliche Verbesserung nur eine Vermutung.","code":"const namen = ['Ada', 'Mina', 'Jonas'];\nconst liste = document.querySelector('#ausgabe');\nconst fragment = document.createDocumentFragment();\nfor (const name of namen) { const li = document.createElement('li'); li.textContent = name; fragment.appendChild(li); }\nliste.appendChild(fragment);","erklaerung":"Eine lange Teilnehmerliste kann beim Aufbau stocken."},{"titel":"DOM-Arbeit bündeln","text":"Wenn du hundertmal nacheinander sichtbare Elemente einfügst, muss der Browser viele Änderungen verwalten. Ein `DocumentFragment` ist wie ein Tablett, auf dem du alle Teller zuerst zusammenstellst. `document.createDocumentFragment()` erzeugt den unsichtbaren Behälter. Füge neue Listenelemente zunächst dort ein. Danach reicht ein gemeinsamer Schritt, um die fertige Gruppe anzuzeigen.","code":"const namen = ['Ada', 'Mina', 'Jonas'];\nconst liste = document.querySelector('#ausgabe');\nconst fragment = document.createDocumentFragment();\nfor (const name of namen) { const li = document.createElement('li'); li.textContent = name; fragment.appendChild(li); }\nliste.appendChild(fragment);","erklaerung":"Wenn du hundertmal nacheinander sichtbare Elemente einfügst, muss der Browser viele Änderungen verwalten."},{"titel":"Elemente sicher erzeugen","text":"Ein Listeneintrag besteht aus einem echten `li`-Element und seinem Text. `document.createElement('li')` erzeugt die Struktur. `li.textContent = name` setzt den Namen, ohne HTML zu interpretieren. `fragment.appendChild(li)` sammelt den Eintrag. So verbindest du sichere Textausgabe und übersichtlichen DOM-Code. Verwende für jede Person ein neues Element.","code":"const namen = ['Ada', 'Mina', 'Jonas'];\nconst liste = document.querySelector('#ausgabe');\nconst fragment = document.createDocumentFragment();\nfor (const name of namen) { const li = document.createElement('li'); li.textContent = name; fragment.appendChild(li); }\nliste.appendChild(fragment);","erklaerung":"Ein Listeneintrag besteht aus einem echten `li`-Element und seinem Text."},{"titel":"Nutzbarkeit vor Mikrooptimierung","text":"Eine schnelle Liste ist wertlos, wenn sie auf dem Telefon nicht bedienbar ist. Prüfe mit Tastatur, Bildschirmleser und schmalem Bildschirm. Bei Tausenden Einträgen kann eine Seiteneinteilung sinnvoller sein als das gleichzeitige Rendern aller Zeilen. Lade nur die Daten, die du wirklich brauchst. Achte darauf, dass die Optimierung keine Inhalte versteckt oder die Reihenfolge unerwartet verändert.","code":"const namen = ['Ada', 'Mina', 'Jonas'];\nconst liste = document.querySelector('#ausgabe');\nconst fragment = document.createDocumentFragment();\nfor (const name of namen) { const li = document.createElement('li'); li.textContent = name; fragment.appendChild(li); }\nliste.appendChild(fragment);","erklaerung":"Eine schnelle Liste ist wertlos, wenn sie auf dem Telefon nicht bedienbar ist."}],"beispiel":{"html":"<h1>Teilnehmerliste</h1><ul id='ausgabe'></ul>","css":"","js":"const namen = ['Ada', 'Mina', 'Jonas'];\nconst liste = document.querySelector('#ausgabe');\nconst fragment = document.createDocumentFragment();\nfor (const name of namen) { const li = document.createElement('li'); li.textContent = name; fragment.appendChild(li); }\nliste.appendChild(fragment);"},"aufgabe":{"text":"Setze „Performance messen und DOM-Arbeit reduzieren“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.","tipp":"Lies den zugehörigen Schritt und vergleiche den Code mit dem erklärten Verhalten.","pruefungen":[{"beschreibung":"Die Oberfläche enthält die benötigten Elemente.","test":"p5-3-html"},{"beschreibung":"Die Technik wurde in JavaScript verwendet.","test":"p5-3-js"}],"loesung":{"html":"<h1>Teilnehmerliste</h1><ul id='ausgabe'></ul>","css":"","js":"const namen = ['Ada', 'Mina', 'Jonas'];\nconst liste = document.querySelector('#ausgabe');\nconst fragment = document.createDocumentFragment();\nfor (const name of namen) { const li = document.createElement('li'); li.textContent = name; fragment.appendChild(li); }\nliste.appendChild(fragment);"}},"fehler":[{"titel":"Text als HTML zusammenbauen","text":"Falsch: `liste.innerHTML += '<li>' + name + '</li>';` parst den gesamten HTML-Inhalt wiederholt und interpretiert fremde Namen als Markup. Richtig: `const li=document.createElement('li'); li.textContent=name; liste.appendChild(li);`."},{"titel":"Ohne Messung Geschwindigkeit behaupten","text":"Falsch: `console.log('Jetzt doppelt so schnell');` beweist keine Verbesserung und liefert keine Laufzeit. Richtig: `const start=performance.now(); rendern(); console.log(performance.now()-start);` misst die tatsächlich benötigte Zeit."}],"quiz":[{"frage":"Was misst performance.now?","antworten":["Die Bildschirmbreite","Zeitpunkte für Laufzeitmessungen","Die Netzgeschwindigkeit direkt"],"richtig":1,"erklaerung":"performance.now liefert Zeitpunkte, deren Differenz die gemessene Dauer ergibt.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Wofür dient ein DocumentFragment?","antworten":["Als Datenbank","Zum Sammeln von DOM-Knoten vor dem Einfügen","Als HTTP-Server"],"richtig":1,"erklaerung":"Ein Fragment sammelt Listenelemente, bevor sie gemeinsam in die Seite eingefügt werden.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Was bleibt bei einer Optimierung wichtig?","antworten":["Barrierefreiheit und korrekte Funktion","Nur wenige Codezeilen","Ein bestimmtes Framework"],"richtig":0,"erklaerung":"Eine Verbesserung muss auch Tastaturbedienung und korrekte Inhalte erhalten.","begruendungen":["Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion."]}],"merke":["Wenn du hundertmal nacheinander sichtbare Elemente einfügst, muss der Browser viele Änderungen verwalten.","Eine schnelle Liste ist wertlos, wenn sie auf dem Telefon nicht bedienbar ist."]},{"id":"p5-4","title":"Automatische Tests für Funktionen","minutes":35,"ziel":"Erwartete Ergebnisse und Grenzfälle prüfen","schritte":[{"titel":"Verhalten vor dem Test beschreiben","text":"Eine Formularprüfung soll leere Eingaben ablehnen und sinnvolle Texte akzeptieren. Schreibe diese Regel zuerst in Alltagssprache auf. Ein Test ist wie eine Checkliste vor dem Öffnen eines Geschäfts: Er vergleicht eine konkrete Eingabe mit einem erwarteten Ergebnis. Prüfe nicht nur den Normalfall, sondern auch Leerzeichen und unerwartete Datentypen. So werden Anforderungen nachvollziehbar.","code":"function istGueltig(text) { return typeof text === 'string' && text.trim().length > 0; }\nconsole.assert(istGueltig('Hallo') === true, 'Text sollte gültig sein');\nconsole.assert(istGueltig('   ') === false, 'Leerzeichen sind ungültig');\ndocument.querySelector('#ausgabe').textContent = 'Zwei Prüfungen ausgeführt';","erklaerung":"Eine Formularprüfung soll leere Eingaben ablehnen und sinnvolle Texte akzeptieren."},{"titel":"Eine reine Funktion bauen","text":"`istGueltig` nimmt einen Wert entgegen und liefert true oder false. `typeof text === 'string'` verhindert, dass die Funktion bei Zahlen unbedacht trim aufruft. `text.trim().length > 0` entfernt gedanklich Rand-Leerzeichen und prüft, ob etwas übrig bleibt. Weil die Funktion keine Webseite verändert, kann ein Test sie direkt aufrufen. Die gleiche Eingabe erzeugt immer das gleiche Ergebnis.","code":"function istGueltig(text) { return typeof text === 'string' && text.trim().length > 0; }\nconsole.assert(istGueltig('Hallo') === true, 'Text sollte gültig sein');\nconsole.assert(istGueltig('   ') === false, 'Leerzeichen sind ungültig');\ndocument.querySelector('#ausgabe').textContent = 'Zwei Prüfungen ausgeführt';","erklaerung":"`istGueltig` nimmt einen Wert entgegen und liefert true oder false."},{"titel":"Mit assert vergleichen","text":"Ein Test prüft die Antwort wie eine Lehrkraft eine Musterlösung. `console.assert(istGueltig('Hallo') === true, 'Text sollte gültig sein')` meldet eine fehlgeschlagene Erwartung in der Konsole. Der zweite Test erwartet false für reine Leerzeichen. `console.assert` ist für eine erste Browserübung geeignet, setzt aber keinen verlässlichen CI-Exitcode. In Node.js nutzt du später `node:test` und `assert` für echte automatisierte Testläufe.","code":"function istGueltig(text) { return typeof text === 'string' && text.trim().length > 0; }\nconsole.assert(istGueltig('Hallo') === true, 'Text sollte gültig sein');\nconsole.assert(istGueltig('   ') === false, 'Leerzeichen sind ungültig');\ndocument.querySelector('#ausgabe').textContent = 'Zwei Prüfungen ausgeführt';","erklaerung":"Ein Test prüft die Antwort wie eine Lehrkraft eine Musterlösung."},{"titel":"Fehler gezielt nachstellen","text":"Ändere absichtlich die Funktion so, dass Leerzeichen als gültig gelten. Der Negativtest muss nun fehlschlagen; sonst prüft er nicht die gewünschte Regel. Stelle danach die korrekte Funktion wieder her. Führe Tests nach jeder Änderung aus, besonders wenn mehrere Funktionen voneinander abhängen. Ein grüner Test beweist nur das geprüfte Verhalten, nicht die vollständige Fehlerfreiheit.","code":"function istGueltig(text) { return typeof text === 'string' && text.trim().length > 0; }\nconsole.assert(istGueltig('Hallo') === true, 'Text sollte gültig sein');\nconsole.assert(istGueltig('   ') === false, 'Leerzeichen sind ungültig');\ndocument.querySelector('#ausgabe').textContent = 'Zwei Prüfungen ausgeführt';","erklaerung":"Ändere absichtlich die Funktion so, dass Leerzeichen als gültig gelten."}],"beispiel":{"html":"<h1>Automatische Tests für Funktionen</h1><p id='ausgabe'></p>","css":"","js":"function istGueltig(text) { return typeof text === 'string' && text.trim().length > 0; }\nconsole.assert(istGueltig('Hallo') === true, 'Text sollte gültig sein');\nconsole.assert(istGueltig('   ') === false, 'Leerzeichen sind ungültig');\ndocument.querySelector('#ausgabe').textContent = 'Zwei Prüfungen ausgeführt';"},"aufgabe":{"text":"Setze „Automatische Tests für Funktionen“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.","tipp":"Lies den zugehörigen Schritt und vergleiche den Code mit dem erklärten Verhalten.","pruefungen":[{"beschreibung":"Die Oberfläche enthält die benötigten Elemente.","test":"p5-4-html"},{"beschreibung":"Die Technik wurde in JavaScript verwendet.","test":"p5-4-js"}],"loesung":{"html":"<h1>Automatische Tests für Funktionen</h1><p id='ausgabe'></p>","css":"","js":"function istGueltig(text) { return typeof text === 'string' && text.trim().length > 0; }\nconsole.assert(istGueltig('Hallo') === true, 'Text sollte gültig sein');\nconsole.assert(istGueltig('   ') === false, 'Leerzeichen sind ungültig');\ndocument.querySelector('#ausgabe').textContent = 'Zwei Prüfungen ausgeführt';"}},"fehler":[{"titel":"Nur den Erfolgsfall prüfen","text":"Falsch: `console.assert(istGueltig('Hallo'));` prüft nicht, ob Leerzeichen fälschlich akzeptiert werden. Richtig: `console.assert(istGueltig('   ') === false);` ergänzt einen wichtigen Grenzfall."},{"titel":"Konsole mit CI verwechseln","text":"Falsch: `console.assert(false);` garantiert keinen fehlgeschlagenen Node-Testlauf. Richtig: `const assert=require('node:assert/strict'); assert.equal(2+2,4);` in einer Node-Testdatei verwendet eine echte Assertion."}],"quiz":[{"frage":"Was ist ein Negativtest?","antworten":["Ein dunkles Theme","Eine entfernte Datei","Ein Test mit einer bewusst ungültigen Eingabe"],"richtig":2,"erklaerung":"Eine ungültige Eingabe wie Leerzeichen gehört ausdrücklich in die Negativtests.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein."]},{"frage":"Warum sind reine Funktionen gut testbar?","antworten":["Sie laden automatisch Webseiten","Sie haben keine versteckten DOM-Seiteneffekte","Sie brauchen nie Parameter"],"richtig":1,"erklaerung":"Reine Funktionen liefern für dieselben Argumente denselben Wert ohne DOM-Seiteneffekte.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Was sollte bei einem absichtlich eingebauten Fehler passieren?","antworten":["Die Tests bleiben grün","Die Seite wird gelöscht","Der passende Test schlägt fehl"],"richtig":2,"erklaerung":"Ein absichtlich eingebauter Defekt muss vom passenden Test erkannt werden.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein."]}],"merke":["`istGueltig` nimmt einen Wert entgegen und liefert true oder false.","Ändere absichtlich die Funktion so, dass Leerzeichen als gültig gelten."]},{"id":"p5-5","title":"Git: Änderungen nachvollziehbar sichern","minutes":35,"ziel":"Status, Stage und Commit unterscheiden","schritte":[{"titel":"Arbeitsverzeichnis verstehen","text":"Beim Schreiben eines Buchs sind nicht alle Änderungen sofort Teil einer veröffentlichten Ausgabe. Git unterscheidet die aktuellen Dateien im Arbeitsverzeichnis von gespeicherten Versionsständen. `git status` zeigt, welche Dateien verändert, neu oder zum Commit vorgemerkt sind. Lies diese Anzeige, bevor du einen Commit erstellst. Prüfe, ob versehentlich persönliche Daten oder große Dateien auftauchen.","code":"const befehle = ['git status', 'git add mein-sd-hub/app.js', 'git commit -m \"Anzeige verbessern\"'];\ndocument.querySelector('#ausgabe').textContent = befehle.join(' → ');","erklaerung":"Beim Schreiben eines Buchs sind nicht alle Änderungen sofort Teil einer veröffentlichten Ausgabe."},{"titel":"Änderungen gezielt vormerken","text":"Mit `git add mein-sd-hub/app.js` legst du genau diese Datei in die Staging Area. Das ist wie die Auswahl der Seiten, die in die nächste Druckauflage sollen. `git add .` würde alle Änderungen im aktuellen Verzeichnis vormerken und kann unerwünschte Dateien erfassen. Kontrolliere deshalb danach erneut `git status`. Ein Commit sollte nur logisch zusammengehörige Änderungen enthalten.","code":"const befehle = ['git status', 'git add mein-sd-hub/app.js', 'git commit -m \"Anzeige verbessern\"'];\ndocument.querySelector('#ausgabe').textContent = befehle.join(' → ');","erklaerung":"Mit `git add mein-sd-hub/app.js` legst du genau diese Datei in die Staging Area."},{"titel":"Einen Commit erstellen","text":"Ein Commit ist ein beschrifteter Schnappschuss der vorgemerkten Änderungen. `git commit -m \"Anzeige verbessern\"` erstellt ihn mit einer kurzen Beschreibung. Die Nachricht erklärt, was sich geändert hat, nicht nur dass irgendetwas passiert ist. Mit `git log --oneline` kannst du die Geschichte später nachverfolgen. Ein lokaler Commit ist noch nicht automatisch auf GitHub verfügbar.","code":"const befehle = ['git status', 'git add mein-sd-hub/app.js', 'git commit -m \"Anzeige verbessern\"'];\ndocument.querySelector('#ausgabe').textContent = befehle.join(' → ');","erklaerung":"Ein Commit ist ein beschrifteter Schnappschuss der vorgemerkten Änderungen."},{"titel":"Sicher mit Fehlern umgehen","text":"Wenn eine Änderung misslingt, solltest du wissen, ob sie bereits gestaged oder committed wurde. `git diff` zeigt ungestagte Unterschiede; `git diff --staged` zeigt die Auswahl für den nächsten Commit. Lies die Unterschiede vor dem Speichern. Verwende keine destruktiven Rücksetzbefehle, ohne ihre Folgen zu verstehen. Halte geheime Schlüssel grundsätzlich außerhalb des Repositorys.","code":"const befehle = ['git status', 'git add mein-sd-hub/app.js', 'git commit -m \"Anzeige verbessern\"'];\ndocument.querySelector('#ausgabe').textContent = befehle.join(' → ');","erklaerung":"Wenn eine Änderung misslingt, solltest du wissen, ob sie bereits gestaged oder committed wurde."}],"beispiel":{"html":"<h1>Git: Änderungen nachvollziehbar sichern</h1><p id='ausgabe'></p>","css":"","js":"const befehle = ['git status', 'git add mein-sd-hub/app.js', 'git commit -m \"Anzeige verbessern\"'];\ndocument.querySelector('#ausgabe').textContent = befehle.join(' → ');"},"aufgabe":{"text":"Setze „Git: Änderungen nachvollziehbar sichern“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.","tipp":"Lies den zugehörigen Schritt und vergleiche den Code mit dem erklärten Verhalten.","pruefungen":[{"beschreibung":"Die Oberfläche enthält die benötigten Elemente.","test":"p5-5-html"},{"beschreibung":"Die Technik wurde in JavaScript verwendet.","test":"p5-5-js"}],"loesung":{"html":"<h1>Git: Änderungen nachvollziehbar sichern</h1><p id='ausgabe'></p>","css":"","js":"const befehle = ['git status', 'git add mein-sd-hub/app.js', 'git commit -m \"Anzeige verbessern\"'];\ndocument.querySelector('#ausgabe').textContent = befehle.join(' → ');"}},"fehler":[{"titel":"Alle Dateien blind vormerken","text":"Falsch: `git add .` ohne Kontrolle kann versehentlich eine Datei mit Zugangsdaten aufnehmen. Richtig: `git status` prüfen und `git add mein-sd-hub/app.js` für gezielt ausgewählte Änderungen nutzen."},{"titel":"Commit mit Veröffentlichung verwechseln","text":"Falsch: `git commit -m 'Fertig'` macht den Stand sofort auf GitHub sichtbar. Richtig: Nach dem lokalen Commit braucht ein verbundenes Remote normalerweise `git push`, bevor andere den Commit sehen."}],"quiz":[{"frage":"Was zeigt git status?","antworten":["Den Zustand der Dateien","Die Browserauflösung","Das CSS-Layout"],"richtig":0,"erklaerung":"git status zeigt, welche Änderungen noch offen oder vorgemerkt sind.","begruendungen":["Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Was macht git add?","antworten":["Merkt Änderungen für einen Commit vor","Löscht die Historie","Veröffentlicht eine Website"],"richtig":0,"erklaerung":"git add wählt Dateien für den nächsten Commit aus, veröffentlicht sie aber nicht.","begruendungen":["Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Was beschreibt eine gute Commit-Nachricht?","antworten":["Nur das Datum","Nur den Benutzernamen","Den Zweck der Änderung"],"richtig":2,"erklaerung":"Eine Commit-Nachricht soll erklären, welche zusammengehörige Änderung gespeichert wurde.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein."]}],"merke":["Mit `git add mein-sd-hub/app.js` legst du genau diese Datei in die Staging Area.","Wenn eine Änderung misslingt, solltest du wissen, ob sie bereits gestaged oder committed wurde."]},{"id":"p5-6","title":"Branches und Pull Requests auf GitHub","minutes":35,"ziel":"Änderungen getrennt prüfen und zusammenführen","schritte":[{"titel":"Eine Aufgabe isolieren","text":"Wenn zwei Personen gleichzeitig an einer Website arbeiten, sollten sie nicht dieselben unfertigen Änderungen direkt in main speichern. Ein Branch ist wie ein eigener Arbeitstisch für ein Vorhaben. `git switch -c feature/lesbarkeit` erstellt und aktiviert einen neuen Branch. Er beginnt am aktuellen Commit. Prüfe vorher, ob dein lokaler main mit dem Remote-Stand übereinstimmt.","code":"const schritte = ['git switch -c feature/lesbarkeit', 'git push -u origin feature/lesbarkeit', 'Pull Request gegen main erstellen'];\ndocument.querySelector('#ausgabe').textContent = schritte.join(' | ');","erklaerung":"Wenn zwei Personen gleichzeitig an einer Website arbeiten, sollten sie nicht dieselben unfertigen Änderungen direkt in main speichern."},{"titel":"Den Branch veröffentlichen","text":"Andere können deine Arbeit erst auf GitHub sehen, wenn du den Branch hochlädst. `git push -u origin feature/lesbarkeit` legt den Branch beim Remote an und verbindet ihn mit dem lokalen. Danach kannst du die Unterschiede online ansehen. Veröffentliche niemals Passwörter, Tokens oder persönliche Daten. Ein Push ist noch kein Merge nach main.","code":"const schritte = ['git switch -c feature/lesbarkeit', 'git push -u origin feature/lesbarkeit', 'Pull Request gegen main erstellen'];\ndocument.querySelector('#ausgabe').textContent = schritte.join(' | ');","erklaerung":"Andere können deine Arbeit erst auf GitHub sehen, wenn du den Branch hochlädst."},{"titel":"Pull Request vorbereiten","text":"Ein Pull Request ist eine Bitte, die Änderungen eines Branches in einen Zielbranch zu übernehmen. Beschreibe, was sich geändert hat, welche Tests liefen und welche Risiken bestehen. Ein Draft-PR signalisiert, dass noch Arbeit aussteht. Bitte bei wichtigen Änderungen um Review. Prüfe im Diff, ob nur die beabsichtigten Dateien geändert wurden.","code":"const schritte = ['git switch -c feature/lesbarkeit', 'git push -u origin feature/lesbarkeit', 'Pull Request gegen main erstellen'];\ndocument.querySelector('#ausgabe').textContent = schritte.join(' | ');","erklaerung":"Ein Pull Request ist eine Bitte, die Änderungen eines Branches in einen Zielbranch zu übernehmen."},{"titel":"Erst nach Prüfungen mergen","text":"Ein grüner Test ist wie eine bestandene Qualitätskontrolle vor der Auslieferung. Warte auf die erforderlichen CI-Prüfungen und lies bei Fehlern die Logs. Aktualisiere den Branch, falls main inzwischen weiterentwickelt wurde. Beim Merge-Commit bleibt die PR-Geschichte nachvollziehbar. Kontrolliere anschließend erneut die Tests auf main, denn die Kombination mehrerer Änderungen kann neue Fehler auslösen.","code":"const schritte = ['git switch -c feature/lesbarkeit', 'git push -u origin feature/lesbarkeit', 'Pull Request gegen main erstellen'];\ndocument.querySelector('#ausgabe').textContent = schritte.join(' | ');","erklaerung":"Ein grüner Test ist wie eine bestandene Qualitätskontrolle vor der Auslieferung."}],"beispiel":{"html":"<h1>Branches und Pull Requests auf GitHub</h1><p id='ausgabe'></p>","css":"","js":"const schritte = ['git switch -c feature/lesbarkeit', 'git push -u origin feature/lesbarkeit', 'Pull Request gegen main erstellen'];\ndocument.querySelector('#ausgabe').textContent = schritte.join(' | ');"},"aufgabe":{"text":"Setze „Branches und Pull Requests auf GitHub“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.","tipp":"Lies den zugehörigen Schritt und vergleiche den Code mit dem erklärten Verhalten.","pruefungen":[{"beschreibung":"Die Oberfläche enthält die benötigten Elemente.","test":"p5-6-html"},{"beschreibung":"Die Technik wurde in JavaScript verwendet.","test":"p5-6-js"}],"loesung":{"html":"<h1>Branches und Pull Requests auf GitHub</h1><p id='ausgabe'></p>","css":"","js":"const schritte = ['git switch -c feature/lesbarkeit', 'git push -u origin feature/lesbarkeit', 'Pull Request gegen main erstellen'];\ndocument.querySelector('#ausgabe').textContent = schritte.join(' | ');"}},"fehler":[{"titel":"Direkt auf main experimentieren","text":"Falsch: Neue ungetestete Funktionen unmittelbar nach main pushen kann die öffentliche Website beeinträchtigen. Richtig: `git switch -c feature/lesbarkeit` verwenden, Tests ausführen und einen Pull Request zur Prüfung erstellen."},{"titel":"Rote CI ignorieren","text":"Falsch: Einen Pull Request trotz fehlgeschlagener Tests mergen und die Ursache später suchen. Richtig: Fehlerlogs lesen, die Ursache beheben und auf einen erfolgreichen erneuten Testlauf warten."}],"quiz":[{"frage":"Wozu dient ein Feature-Branch?","antworten":["Zum Löschen von Tests","Zum isolierten Arbeiten","Zum Erstellen von HTML"],"richtig":1,"erklaerung":"Ein Feature-Branch hält unfertige Änderungen von der stabilen Hauptentwicklung getrennt.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Was ist ein Pull Request?","antworten":["Ein Browser-Cache","Eine Python-Bibliothek","Ein Vorschlag zum Zusammenführen von Änderungen"],"richtig":2,"erklaerung":"Ein Pull Request zeigt den vorgeschlagenen Unterschied zwischen Arbeits- und Zielbranch.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein."]},{"frage":"Wann sollte gemergt werden?","antworten":["Vor dem Schreiben der Tests","Nach Review und erfolgreichen erforderlichen Prüfungen","Sobald eine Datei existiert"],"richtig":1,"erklaerung":"Vor dem Merge müssen Review und erforderliche CI-Prüfungen erfolgreich sein.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion."]}],"merke":["Andere können deine Arbeit erst auf GitHub sehen, wenn du den Branch hochlädst.","Ein grüner Test ist wie eine bestandene Qualitätskontrolle vor der Auslieferung."]},{"id":"p5-7","title":"Webseite sicher veröffentlichen","minutes":35,"ziel":"Build, Pfade und Deployment überprüfen","schritte":[{"titel":"Eine veröffentlichbare Version prüfen","text":"Eine Webseite funktioniert auf dem eigenen Rechner, aber das garantiert noch keinen erfolgreichen öffentlichen Aufruf. Überprüfe die Startseite, alle verlinkten Dateien und die mobile Ansicht. Achte auf Groß- und Kleinschreibung in Dateinamen; Webserver unterscheiden sie häufig. Öffne die Browserkonsole und suche nach Ladefehlern. Ein einfacher Test auf localhost ersetzt keine Kontrolle der tatsächlichen Internetadresse.","code":"const pruefpunkte = ['Startseite erreichbar', 'relative Pfade geprüft', 'HTTPS aktiv'];\ndocument.querySelector('#ausgabe').textContent = pruefpunkte.join(', ');","erklaerung":"Eine Webseite funktioniert auf dem eigenen Rechner, aber das garantiert noch keinen erfolgreichen öffentlichen Aufruf."},{"titel":"Dateipfade verstehen","text":"Ein Bildpfad `./bilder/logo.svg` ist relativ zur aktuellen Datei. Ein Pfad `/bilder/logo.svg` beginnt dagegen an der Wurzel der Website. Wenn ein Projekt unter einem Unterordner veröffentlicht wird, kann ein falscher absoluter Pfad zu 404 führen. Plane deshalb die Zieladresse frühzeitig ein. Prüfe CSS-, JavaScript- und Bilddateien auf der veröffentlichten Seite.","code":"const pruefpunkte = ['Startseite erreichbar', 'relative Pfade geprüft', 'HTTPS aktiv'];\ndocument.querySelector('#ausgabe').textContent = pruefpunkte.join(', ');","erklaerung":"Ein Bildpfad `./bilder/logo.svg` ist relativ zur aktuellen Datei."},{"titel":"Deployment beobachten","text":"Ein Hosting-Dienst kann aus dem Repository eine neue Website-Version bereitstellen. GitHub Pages zeigt einen eigenen Build- und Deployment-Status. Ein erfolgreicher Code-Test ist nicht automatisch ein erfolgreicher Pages-Deploy. Warte auf die Abschlussmeldung und kontrolliere die tatsächlich ausgelieferte URL. Bei einem Fehler solltest du das Deployment-Log lesen und die Ursache beheben.","code":"const pruefpunkte = ['Startseite erreichbar', 'relative Pfade geprüft', 'HTTPS aktiv'];\ndocument.querySelector('#ausgabe').textContent = pruefpunkte.join(', ');","erklaerung":"Ein Hosting-Dienst kann aus dem Repository eine neue Website-Version bereitstellen."},{"titel":"Sicherheit und Aktualität","text":"Eine öffentliche Website sollte über HTTPS erreichbar sein. Veröffentliche keine privaten Zugangsdaten im JavaScript oder Repository. Prüfe, ob Formulare verständliche Fehlermeldungen anzeigen und die Navigation mit der Tastatur funktioniert. Nach der Veröffentlichung können alte Dateien im Browsercache liegen; kontrolliere daher auch die Aktualisierung. Halte eine bekannte funktionierende Version für einen Rückweg bereit.","code":"const pruefpunkte = ['Startseite erreichbar', 'relative Pfade geprüft', 'HTTPS aktiv'];\ndocument.querySelector('#ausgabe').textContent = pruefpunkte.join(', ');","erklaerung":"Eine öffentliche Website sollte über HTTPS erreichbar sein."}],"beispiel":{"html":"<h1>Webseite sicher veröffentlichen</h1><p id='ausgabe'></p>","css":"","js":"const pruefpunkte = ['Startseite erreichbar', 'relative Pfade geprüft', 'HTTPS aktiv'];\ndocument.querySelector('#ausgabe').textContent = pruefpunkte.join(', ');"},"aufgabe":{"text":"Setze „Webseite sicher veröffentlichen“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.","tipp":"Lies den zugehörigen Schritt und vergleiche den Code mit dem erklärten Verhalten.","pruefungen":[{"beschreibung":"Die Oberfläche enthält die benötigten Elemente.","test":"p5-7-html"},{"beschreibung":"Die Technik wurde in JavaScript verwendet.","test":"p5-7-js"}],"loesung":{"html":"<h1>Webseite sicher veröffentlichen</h1><p id='ausgabe'></p>","css":"","js":"const pruefpunkte = ['Startseite erreichbar', 'relative Pfade geprüft', 'HTTPS aktiv'];\ndocument.querySelector('#ausgabe').textContent = pruefpunkte.join(', ');"}},"fehler":[{"titel":"Nur lokalen Aufruf prüfen","text":"Falsch: `http://localhost:8000` funktioniert, also ist die Seite automatisch öffentlich erreichbar. Richtig: Nach dem Deployment die echte HTTPS-Adresse öffnen und alle Ressourcen sowie Browserfehler prüfen."},{"titel":"Tests mit Deployment verwechseln","text":"Falsch: Eine grüne Unit-Test-Action bedeutet, dass GitHub Pages die neue Seite bereits ausliefert. Richtig: Den separaten Pages-Build und die erfolgreiche Bereitstellung kontrollieren."}],"quiz":[{"frage":"Was ist nach dem Deployment zu prüfen?","antworten":["Nur der Editor","Nur die Commit-Nachricht","Die echte öffentliche URL"],"richtig":2,"erklaerung":"Die öffentliche URL beweist, ob die veröffentlichte Version tatsächlich erreichbar ist.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein."]},{"frage":"Was bedeutet ein 404 bei einer Ressource?","antworten":["Ein erfolgreicher Test","Ein gültiges CSS-Layout","Die Datei wurde unter diesem Pfad nicht gefunden"],"richtig":2,"erklaerung":"Ein HTTP-Status 404 bedeutet, dass die angeforderte Ressource am Pfad fehlt.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein."]},{"frage":"Was ist für öffentliche Webseiten wichtig?","antworten":["HTTPS und keine veröffentlichten Geheimnisse","Passwörter im JavaScript","Nur Desktop-Bedienung"],"richtig":0,"erklaerung":"HTTPS und der Schutz geheimer Daten gehören zur Freigabe einer öffentlichen Seite.","begruendungen":["Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion."]}],"merke":["Ein Bildpfad `./bilder/logo.svg` ist relativ zur aktuellen Datei.","Eine öffentliche Website sollte über HTTPS erreichbar sein."]},{"id":"p5-8","title":"Abschlussprojekt: barrierefreie Aufgaben-App","minutes":35,"ziel":"Sichere Ausgabe, Testbarkeit und Bedienbarkeit kombinieren","schritte":[{"titel":"Anforderungen konkretisieren","text":"Deine Aufgaben-App soll Einträge aufnehmen, leere Texte ablehnen und die Aufgaben als echte Liste anzeigen. Schreibe diese drei Regeln auf, bevor du programmierst. Eine gute App lässt sich mit Tastatur und Smartphone bedienen. Das Eingabefeld braucht eine sichtbare Beschriftung, der Knopf einen verständlichen Namen. Speichere zunächst keine sensiblen Daten; für das Abschlussprojekt genügt eine lokale Liste.","code":"function aufgabe(text) { return { text: text.trim(), erledigt: false }; }\nconst eingabe = document.querySelector('#eingabe');\nconst liste = document.querySelector('#liste');\ndocument.querySelector('#hinzufuegen').addEventListener('click', () => { const text = eingabe.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = aufgabe(text).text; liste.appendChild(li); eingabe.value = ''; });","erklaerung":"Deine Aufgaben-App soll Einträge aufnehmen, leere Texte ablehnen und die Aufgaben als echte Liste anzeigen."},{"titel":"Eingabe von Darstellung trennen","text":"`function aufgabe(text) { return { text: text.trim(), erledigt: false }; }` erzeugt ein Datenobjekt und ist ohne Browser testbar. Die Klickfunktion liest dagegen den aktuellen Wert aus dem Eingabefeld. `if (!text) return;` verhindert einen leeren Eintrag. So bleiben Regeln und Bedienung getrennt. Später könntest du die Datenfunktion in ein eigenes Modul verschieben.","code":"function aufgabe(text) { return { text: text.trim(), erledigt: false }; }\nconst eingabe = document.querySelector('#eingabe');\nconst liste = document.querySelector('#liste');\ndocument.querySelector('#hinzufuegen').addEventListener('click', () => { const text = eingabe.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = aufgabe(text).text; liste.appendChild(li); eingabe.value = ''; });","erklaerung":"`function aufgabe(text) { return { text: text.trim(), erledigt: false }; }` erzeugt ein Datenobjekt und ist ohne Browser testbar."},{"titel":"DOM sicher aktualisieren","text":"Eine Aufgabe darf HTML-ähnliche Zeichen enthalten, ohne dass die Webseite sie ausführt. `document.createElement('li')` erzeugt den Listeneintrag. `li.textContent = aufgabe(text).text` setzt den Inhalt als reinen Text. `liste.appendChild(li)` hängt den Eintrag an die Liste. Teste ausdrücklich einen Text wie `<Hallo>` und prüfe, dass die Zeichen sichtbar bleiben.","code":"function aufgabe(text) { return { text: text.trim(), erledigt: false }; }\nconst eingabe = document.querySelector('#eingabe');\nconst liste = document.querySelector('#liste');\ndocument.querySelector('#hinzufuegen').addEventListener('click', () => { const text = eingabe.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = aufgabe(text).text; liste.appendChild(li); eingabe.value = ''; });","erklaerung":"Eine Aufgabe darf HTML-ähnliche Zeichen enthalten, ohne dass die Webseite sie ausführt."},{"titel":"Abschluss und Qualität sichern","text":"Teste mindestens vier Fälle: normaler Text, Leerzeichen, spitze Klammern und mehrere Einträge nacheinander. Prüfe danach die Seite bei 320 Pixel Breite und nur mit der Tastatur. Die App soll ohne externe Bibliotheken funktionieren. Dokumentiere im Git-Commit, welche Regeln umgesetzt wurden. Vor einer Veröffentlichung sind zusätzlich die Browserkonsole und der tatsächliche Deployment-Status zu prüfen.","code":"function aufgabe(text) { return { text: text.trim(), erledigt: false }; }\nconst eingabe = document.querySelector('#eingabe');\nconst liste = document.querySelector('#liste');\ndocument.querySelector('#hinzufuegen').addEventListener('click', () => { const text = eingabe.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = aufgabe(text).text; liste.appendChild(li); eingabe.value = ''; });","erklaerung":"Teste mindestens vier Fälle: normaler Text, Leerzeichen, spitze Klammern und mehrere Einträge nacheinander."}],"beispiel":{"html":"<h1>Meine Aufgaben</h1><label for='eingabe'>Neue Aufgabe</label><input id='eingabe'><button id='hinzufuegen' type='button'>Hinzufügen</button><ul id='liste'></ul>","css":"","js":"function aufgabe(text) { return { text: text.trim(), erledigt: false }; }\nconst eingabe = document.querySelector('#eingabe');\nconst liste = document.querySelector('#liste');\ndocument.querySelector('#hinzufuegen').addEventListener('click', () => { const text = eingabe.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = aufgabe(text).text; liste.appendChild(li); eingabe.value = ''; });"},"aufgabe":{"text":"Setze „Abschlussprojekt: barrierefreie Aufgaben-App“ praktisch um. Prüfe die Ausgabe, verändere eine Eingabe und beobachte das Ergebnis.","tipp":"Lies den zugehörigen Schritt und vergleiche den Code mit dem erklärten Verhalten.","pruefungen":[{"beschreibung":"Die Oberfläche enthält die benötigten Elemente.","test":"p5-8-html"},{"beschreibung":"Die Technik wurde in JavaScript verwendet.","test":"p5-8-js"}],"loesung":{"html":"<h1>Meine Aufgaben</h1><label for='eingabe'>Neue Aufgabe</label><input id='eingabe'><button id='hinzufuegen' type='button'>Hinzufügen</button><ul id='liste'></ul>","css":"","js":"function aufgabe(text) { return { text: text.trim(), erledigt: false }; }\nconst eingabe = document.querySelector('#eingabe');\nconst liste = document.querySelector('#liste');\ndocument.querySelector('#hinzufuegen').addEventListener('click', () => { const text = eingabe.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = aufgabe(text).text; liste.appendChild(li); eingabe.value = ''; });"}},"fehler":[{"titel":"Leere Einträge zulassen","text":"Falsch: `liste.appendChild(document.createElement('li'))` bei jeder Eingabe erzeugt auch für Leerzeichen leere Aufgaben. Richtig: `const text=eingabe.value.trim(); if (!text) return;` vor dem Erstellen des Listeneintrags verwenden."},{"titel":"Unkontrollierte Eingabe als HTML setzen","text":"Falsch: `li.innerHTML = eingabe.value;` interpretiert eingegebenes Markup. Richtig: `li.textContent = eingabe.value.trim();` zeigt die Aufgabe sicher als Text."}],"quiz":[{"frage":"Wie wird eine leere Aufgabe abgefangen?","antworten":["Mit trim und einer Leerprüfung","Mit innerHTML","Mit einem CSS-Filter"],"richtig":0,"erklaerung":"trim entfernt Rand-Leerzeichen und ermöglicht die Prüfung auf leere Aufgaben.","begruendungen":["Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Wozu dient ein label?","antworten":["Zum Löschen des Formulars","Zur verständlichen Beschriftung eines Eingabefeldes","Zum Starten von Git"],"richtig":1,"erklaerung":"Ein label verknüpft eine sichtbare Beschriftung mit dem Eingabefeld.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion."]},{"frage":"Welche Prüfung gehört zum Abschluss?","antworten":["Nur eine Desktop-Ansicht","Tastatur, mobile Breite und fehlerhafte Eingaben","Nur ein Screenshot"],"richtig":1,"erklaerung":"Die App muss auch mit Tastatur, kleinen Bildschirmen und ungewöhnlichen Eingaben funktionieren.","begruendungen":["Diese Aussage widerspricht der erklärten Funktion.","Das stimmt mit der beschriebenen Technik überein.","Diese Aussage widerspricht der erklärten Funktion."]}],"merke":["`function aufgabe(text) { return { text: text.trim(), erledigt: false }; }` erzeugt ein Datenobjekt und ist ohne Browser testbar.","Teste mindestens vier Fälle: normaler Text, Leerzeichen, spitze Klammern und mehrere Einträge nacheinander."]}];if(typeof module!=="undefined"&&module.exports)module.exports=root.SDAkademieKurse["saubere-webapps"];})(typeof window!=="undefined"?window:globalThis);
